def clean(fragment):
 s=BeautifulSoup(fragment,'html.parser')
 for el in s.select('section'):
  el['class']=[c for c in el.get('class',[]) if c not in ['faq','contact','conversation']]
 for a in s.select('a[href]'):
  href=a['href'];a['href']={'#application':'apply.html','#contact':'contact.html','#schedule':'contact.html#callback','#rate-inquiry':'get-rate.html','#careers':'careers.html','#finder':'solutions.html#finder','#':'index.html'}.get(href,href)
 return str(s)

def link(file,label,current):
 return f'<a href="{file}"'+(' aria-current="page"' if file==current else '')+f'>{label}</a>'
