def contact_icon(kind,large=False):
 return '<svg class="contact-mark'+(' contact-mark-large' if large else '')+'" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+CONTACT_PATHS[kind]+'</svg>'
def add_contact_icons(html):
 soup=BeautifulSoup(html,'html.parser')
 for a in soup.select('a[href]'):
  href=a['href'];kind='email' if href.startswith('mailto:') else 'phone' if href.startswith('tel:') else 'whatsapp' if 'wa.me/' in href else None
  if kind:
   a['class']=a.get('class',[])+['icon-contact-link'];a.insert(0,BeautifulSoup(contact_icon(kind),'html.parser'))
 for article,kind in zip(soup.select('.contact-methods article'),['email','phone','whatsapp']):article.insert(0,BeautifulSoup(contact_icon(kind,True),'html.parser'))
 for h in soup.select('#offices h3'):h.insert(0,BeautifulSoup(contact_icon('location'),'html.parser'))
 return str(soup)
def render(file,title,body,description='Business financing, invoice factoring, and working capital with Blu Capital.'):
 photos={p['page']:p['file'] for p in json.loads((ROOT/'page-photos.json').read_text())}
 if file in photos:body=body.replace('<section class="page-intro">','<section class="page-intro" style="--page-photo:url('+photos[file]+')">',1)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Blu Capital</title><meta name="description" content="{escape(description)}"><link rel="icon" href="logo_sm.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="site.css"></head><body>{nav(file)}<main id="main">{body}</main>{footer()}{chat}<script src="site.js" defer></script><script src="chat.js" defer></script></body></html>'''
 (DIST/file).write_text(add_contact_icons(html))

